package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	TenantID  string   `json:"tenant_id"`
	Filters   []Filter `json:"filters"`
	OrderBy   string   `json:"order_by"`
	Direction string   `json:"direction"`
}

type Filter struct {
	Field    string `json:"field"`
	Operator string `json:"operator"`
	Value    string `json:"value"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

var allowedFields = map[string]bool{
	"name": true, "email": true, "created_at": true,
	"status": true, "department": true, "role": true,
}

var allowedOperators = map[string]bool{
	"=": true, "!=": true, "LIKE": true, ">": true, "<": true,
}

func buildQuery(req SearchRequest) (string, []interface{}) {
	base := "SELECT id, name, email, status FROM users WHERE tenant_id = $1"
	args := []interface{}{req.TenantID}
	paramIdx := 2

	for _, f := range req.Filters {
		if !allowedFields[f.Field] {
			continue
		}
		if !allowedOperators[strings.ToUpper(f.Operator)] {
			continue
		}
		// Parameterized value for safety
		base += fmt.Sprintf(" AND %s %s $%d", f.Field, f.Operator, paramIdx)
		args = append(args, f.Value)
		paramIdx++
	}

	// ORDER BY clause - validated against allowed fields
	if req.OrderBy != "" {
		if allowedFields[req.OrderBy] {
			dir := "ASC"
			if strings.ToUpper(req.Direction) == "DESC" {
				dir = "DESC"
			}
			// BUG: OrderBy is validated but Direction raw value is used in error path
			base += " ORDER BY " + req.OrderBy + " " + dir
		}
	}

	return base, args
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid json", 400)
		return
	}

	// Tenant isolation check - but tenant_id comes from request body
	if req.TenantID == "" {
		http.Error(w, "tenant_id required", 400)
		return
	}

	query, args := buildQuery(req)

	rows, err := db.Query(query, args...)
	if err != nil {
		// Verbose error for debugging - leaks query structure
		log.Printf("Query error: %v | Query: %s | Args: %v", err, query, args)
		http.Error(w, fmt.Sprintf("query failed: %v", err), 500)
		return
	}
	defer rows.Close()

	var results []map[string]interface{}
	for rows.Next() {
		var id int
		var name, email, status string
		rows.Scan(&id, &name, &email, &status)
		results = append(results, map[string]interface{}{
			"id": id, "name": name, "email": email, "status": status,
		})
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v2/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
